param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'decimal-parse-trailing-nul-styles-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$delegates=@{};$span=[ReadOnlySpan``1].MakeGenericType([char]);$asSpan=[MemoryExtensions].GetMethod('AsSpan',[type[]]@([string]))
foreach($route in @('string','chars')){foreach($trying in @($false,$true)){$types=[type[]]@([string],[Globalization.NumberStyles],[IFormatProvider]);if($route -eq 'chars'){$types[0]=$span};if($trying){$types+=[decimal].MakeByRefType()};$method=[decimal].GetMethod($(if($trying){'TryParse'}else{'Parse'}),([type[]]$types));$returnType=$(if($trying){[bool]}else{[decimal]});$parameters=[type[]]@([string],[int],[IFormatProvider],[decimal[]]);$dm=[Reflection.Emit.DynamicMethod]::new('ParseStyleGuard',$returnType,$parameters);$il=$dm.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);if($route -eq 'chars'){$il.Emit([Reflection.Emit.OpCodes]::Call,$asSpan)};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);if($trying){$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[decimal])};$il.Emit([Reflection.Emit.OpCodes]::Call,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$delegateType=[Linq.Expressions.Expression]::GetDelegateType([type[]]@([string],[int],[IFormatProvider],[decimal[]],$returnType));$delegates["$route/$trying"]=$dm.CreateDelegate($delegateType)}}
$rows=[Collections.Generic.List[object]]::new();foreach($style in $plan.styles){foreach($text in $plan.texts){foreach($route in @('string','chars')){foreach($trying in @($false,$true)){$holder=[decimal[]]@([decimal]123);$arguments=[object[]]::new(4);$arguments[0]=$text;$arguments[1]=[int]$style;$arguments[2]=[Globalization.NumberFormatInfo]::InvariantInfo;$arguments[3]=$holder;try{$value=$delegates["$route/$trying"].DynamicInvoke($arguments);if($trying){$result=[ordered]@{ok=$true;value=[bool]$value}}else{$result=[ordered]@{ok=$true;bits=[decimal]::GetBits([decimal]$value)}}}catch{$result=Failure $_};$rows.Add([ordered]@{style=$style;text=$text;route=$route;trying=$trying;result=$result;afterBits=[decimal]::GetBits($holder[0])})}}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS invalid Decimal styles: $($rows.Count) calls"
